defined('ABSPATH')||exit; class CFP_Elementor_Widget extends \Elementor\Widget_Base{private string $wid; private string $label; public function __construct(string $id='',string $label='',array $data=array(),$args=null){$this->wid=$id?:'cfp_widget';$this->label=$label?:'ConversionFlow Widget';parent::__construct($data,$args);} public static function definitions():array{return array('cfp_checkout'=>'Funnel Checkout','cfp_order_bump'=>'Order Bump','cfp_upsell'=>'One Click Upsell Offer','cfp_downsell'=>'Downsell Offer','cfp_product_offer'=>'Dynamic Product Offer','cfp_order_summary'=>'Dynamic Order Summary','cfp_customer_details'=>'Customer Details','cfp_thank_you'=>'Thank You Order Details','cfp_downloads'=>'Download Files','cfp_countdown'=>'Countdown Timer','cfp_cta'=>'CTA Button','cfp_testimonials'=>'Testimonials','cfp_faq'=>'FAQ Accordion','cfp_guarantee'=>'Guarantee Box','cfp_pricing'=>'Pricing Table','cfp_vsl'=>'Video Sales Letter','cfp_progress'=>'Progress Bar','cfp_step_indicator'=>'Funnel Step Indicator','cfp_coupon'=>'Coupon Box','cfp_recommended'=>'Recommended Products');} public function get_name(){return $this->wid;} public function get_title(){return $this->label;} public function get_icon(){return 'eicon-cart-medium';} public function get_categories(){return array('conversionflow-pro');} protected function register_controls(){ $this->start_controls_section('content',array('label'=>__('Content','conversionflow-pro'))); $this->add_control('headline',array('label'=>__('Headline','conversionflow-pro'),'type'=>\Elementor\Controls_Manager::TEXT,'default'=>$this->label)); $this->end_controls_section(); $this->start_controls_section('style',array('label'=>__('Style','conversionflow-pro'),'tab'=>\Elementor\Controls_Manager::TAB_STYLE)); $this->add_control('color',array('label'=>__('Color','conversionflow-pro'),'type'=>\Elementor\Controls_Manager::COLOR,'selectors'=>array('{{WRAPPER}} .cfp-widget'=>'color: {{VALUE}}'))); $this->add_group_control(\Elementor\Group_Control_Typography::get_type(),array('name'=>'typography','selector'=>'{{WRAPPER}} .cfp-widget')); $this->add_group_control(\Elementor\Group_Control_Border::get_type(),array('name'=>'border','selector'=>'{{WRAPPER}} .cfp-widget')); $this->add_responsive_control('padding',array('label'=>__('Spacing','conversionflow-pro'),'type'=>\Elementor\Controls_Manager::DIMENSIONS,'selectors'=>array('{{WRAPPER}} .cfp-widget'=>'padding: {{TOP}}{{UNIT}} {{RIGHT}}{{UNIT}} {{BOTTOM}}{{UNIT}} {{LEFT}}{{UNIT}};'))); $this->end_controls_section(); } protected function render(){ $s=$this->get_settings_for_display(); echo '<div class="cfp-widget cfp-widget-'.esc_attr($this->wid).'"><h3>'.esc_html($s['headline']??$this->label).'</h3>'; if('cfp_checkout'===$this->wid){echo do_shortcode('[cfp_checkout]');} elseif('cfp_downloads'===$this->wid){echo do_shortcode('[conversionflow_step type="delivery"]');} else {echo '<p>'.esc_html__('Configure this ConversionFlow widget in Elementor.','conversionflow-pro').'</p>';} echo '</div>';}}
